package formatter

import (
 "math"
 "strconv"
)

func Render(v float64) string {
 if v == 0 {
  if math.Signbit(v) { return "-0" }
  return "0"
 }
 rendered := strconv.FormatFloat(v, 'f', -1, 64)
 if v > 0 { return "+" + rendered }
 return rendered
}

func RenderWithUnit(v float64, unit string) string {
 rendered := Render(v)
 if unit == "" { return rendered }
 return rendered + " " + unit
}

